Given an integer n and an n × n matrix, check whether the matrix is a Magic Square or not. A Magic Square is a matrix containing distinct elements from 1 to n * n such that the sum of every row, every column, and both diagonals is the same.Examples:Input: mat =   [[2, 7, 6],    [[9, 5, 1],    [4, 3, 8]]Output: "Magic Square"Explanation:  Input: mat = [[1, 2], [3, 4]]Output: "Not a Magic Square"Explanation:  Input: mat = [[1, 1, 1], [1, 1, 1], [1, 1, 1]]Output: "Not a Magic Square"Explanation: All sums are same but all elements from 1 to n * n are not present.Try It YourselfTable of Content[Naive Approach] Using Diagonal and Row-Column Sum Verification - O(n * n) Time and O(n * n) Space[Expected Approach] Using a Single Pass - O(n * n) Time and O(n * n) Space[Naive Approach] Using Diagonal and Row-Column Sum Verification - O(n * n) Time and O(n * n) SpaceUse a boolean array to track visited items for uniqueness (all numbers from 1 to n*n should appear once)Compute sum of first row (let us call this sum as target) so that we can match it later with every row, column and diagonalTraverse the matrix and compute row and column sums and compare with the target. If not same, then return false. Also check if a visited item appears again, then return false.Traverse both diagonals and compare the sums with the target sum.
            C++

    #include <iostream>
#include <vector>
using namespace std;

bool isMagicSquare(vector<vector<int>>& mat) {
    int n = mat.size();  
    int target = 0;

    // first row sum
    for (int j = 0; j < n; j++)
        target += mat[0][j];

    // track uniqueness
    vector<int> visited(n*n + 1, 0); 

    for (int i = 0; i < n; i++) {
        int rowSum = 0, colSum = 0;

        for (int j = 0; j < n; j++) {
            rowSum += mat[i][j];
            colSum += mat[j][i];

            int val = mat[i][j];

            // range + duplicate check
            if (val < 1 || val > n*n || visited[val])
                return false;
            visited[val] = 1;
        }

        if (rowSum != target || colSum != target)
            return false;
    }

    int d1 = 0, d2 = 0;

    // diagonals
    for (int i = 0; i < n; i++) {
        d1 += mat[i][i];
        d2 += mat[i][n-i-1];
    }

    return d1 == target && d2 == target;
}

int main() {
    vector<vector<int>> mat = {
        {2,7,6},
        {9,5,1},
        {4,3,8}
    };

    cout << (isMagicSquare(mat) ? "Magic Square" : "Not a Magic Square");
    return 0;
}


